const params = new URLSearchParams();

const agencyClientName = $env.VK_ADS_AGENCY_CLIENT_NAME;
const agencyClientId = $env.VK_ADS_AGENCY_CLIENT_ID;

params.set('grant_type', agencyClientName || agencyClientId ? 'agency_client_credentials' : 'client_credentials');
params.set('client_id', $env.VK_ADS_CLIENT_ID);
params.set('client_secret', $env.VK_ADS_CLIENT_SECRET);

if (agencyClientName) {
  params.set('agency_client_name', agencyClientName);
}

if (agencyClientId) {
  params.set('agency_client_id', agencyClientId);
}

return [
  {
    json: {
      auth_body: params.toString(),
      form_ids: $env.VK_ADS_FORM_IDS || '699269,650806,687948,681771',
    },
  },
];

function normalizePhone(value) {
  if (!value) return null;

  const digits = String(value).replace(/\D+/g, '');

  if (digits.length === 11 && digits.startsWith('8')) return `+7${digits.slice(1)}`;
  if (digits.length === 11 && digits.startsWith('7')) return `+${digits}`;
  if (digits.length === 10) return `+7${digits}`;

  return value;
}

function answerValue(answer) {
  if (!answer) return '';
  if (answer.answer_text) return answer.answer_text;
  if (answer.answer) return answer.answer;
  if (answer.value) return answer.value;
  if (Array.isArray(answer.answer_options)) {
    return answer.answer_options.map((option) => option.text || option.value || option.id).filter(Boolean).join(', ');
  }
  return '';
}

function answerQuestion(answer) {
  return answer?.question_text || answer?.question || answer?.name || '';
}

function findAnswer(answers, patterns) {
  const found = answers.find((answer) => {
    const question = answerQuestion(answer).toLowerCase();
    return patterns.some((pattern) => question.includes(pattern));
  });

  return found ? answerValue(found) : null;
}

const payload = $json;
const leads = payload.items || [];
const out = [];

for (const lead of leads) {
  const contact = lead.contact_info || {};
  const answers = Array.isArray(lead.answers) ? lead.answers : [];
  const contactName = contact.first_name || contact.name || lead.name || 'Без имени';

  out.push({
    json: {
      source_key: `${lead.form_id}:${lead.id}`,
      vk_lead_id: lead.id,
      form_id: lead.form_id,
      form_name: lead.form_name,
      contact_name: contactName,
      phone: normalizePhone(contact.phone),
      email: contact.email || null,
      child_name: findAnswer(answers, ['имя ребенка', 'имя ребёнка']),
      child_age: findAnswer(answers, ['возраст']),
      location: findAnswer(answers, ['локац', 'школ', 'филиал']),
      campaign_id: lead.ad_plan_id || null,
      ad_group_id: lead.ad_group_id || null,
      banner_id: lead.banner_id || null,
      created_at: lead.created_at || null,
      deal_name: `VK Ads: ${lead.form_name || lead.form_id} - ${contactName}`,
      raw: lead,
    },
  });
}

return out;

const data = $getWorkflowStaticData('global');
data.processedVkAdsLeads = data.processedVkAdsLeads || {};

return $input.all().filter((item) => {
  const key = item.json.source_key;
  return key && !data.processedVkAdsLeads[key];
});

