={{ (() => {
  const field = (envName, value) => {
    const id = $env[envName];
    if (!id || value === undefined || value === null || value === '') return null;
    return { field_id: Number(id), values: [{ value: String(value) }] };
  };

  const leadFields = [
    field('AMO_FIELD_FORM_ID', $json.form_id),
    field('AMO_FIELD_FORM_NAME', $json.form_name),
    field('AMO_FIELD_CHILD_NAME', $json.child_name),
    field('AMO_FIELD_CHILD_AGE', $json.child_age),
    field('AMO_FIELD_LOCATION', $json.location),
    field('AMO_FIELD_CAMPAIGN_ID', $json.campaign_id),
    field('AMO_FIELD_AD_GROUP_ID', $json.ad_group_id),
    field('AMO_FIELD_BANNER_ID', $json.banner_id),
  ].filter(Boolean);

  const contactFields = [];
  if ($json.phone) contactFields.push({ field_code: 'PHONE', values: [{ value: $json.phone, enum_code: 'WORK' }] });
  if ($json.email) contactFields.push({ field_code: 'EMAIL', values: [{ value: $json.email, enum_code: 'WORK' }] });

  const lead = {
    name: $json.deal_name,
    pipeline_id: Number($env.AMO_PIPELINE_ID),
    status_id: Number($env.AMO_STATUS_ID),
    custom_fields_values: leadFields.length ? leadFields : undefined,
    _embedded: {
      contacts: [
        {
          first_name: $json.contact_name || 'Без имени',
          custom_fields_values: contactFields.length ? contactFields : undefined,
        },
      ],
    },
  };

  if ($env.AMO_RESPONSIBLE_USER_ID) lead.responsible_user_id = Number($env.AMO_RESPONSIBLE_USER_ID);

  return [lead];
})() }}

