const data = $getWorkflowStaticData('global');
data.processedVkAdsLeads = data.processedVkAdsLeads || {};

const sourceItems = $('Filter new leads').all();
const out = [];

for (const [index, item] of $input.all().entries()) {
  const source = sourceItems[index]?.json;

  if (source?.source_key) {
    data.processedVkAdsLeads[source.source_key] = {
      processed_at: new Date().toISOString(),
      amo_response: item.json,
    };
  }

  out.push({
    json: {
      source_key: source?.source_key,
      vk_lead_id: source?.vk_lead_id,
      form_id: source?.form_id,
      amo_response: item.json,
    },
  });
}

return out;
